def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = me[-1]
    last_op = op[-1]

    opp_c = 0
    my_c = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    d_to_c = 0
    d_to_d = 0
    op_alt = 0

    for i in range(n):
        a = me[i]
        b = op[i]
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
        if a == 'C':
            if b == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if b == 'C':
                dc += 1
            else:
                dd += 1
        if i < n - 1 and a == 'D':
            if op[i + 1] == 'C':
                d_to_c += 1
            else:
                d_to_d += 1
        if i > 0 and op[i] != op[i - 1]:
            op_alt += 1

    opp_d = n - opp_c
    my_d = n - my_c

    start = n - 12 if n > 12 else 0
    rec_len = n - start
    r_opp_c = 0
    r_opp_d = 0
    r_my_d = 0
    for i in range(start, n):
        if op[i] == 'C':
            r_opp_c += 1
        else:
            r_opp_d += 1
        if me[i] == 'D':
            r_my_d += 1

    pure_d = opp_c == 0 and n >= 2
    very_nice = (
        n >= 5
        and opp_c >= n - 1
        and (rec_len <= 4 or r_opp_c >= rec_len - 1)
    )
    nice = (n >= 5 and opp_c >= n - 3) or (rec_len >= 6 and r_opp_c >= 5)
    hostile = (
        pure_d
        or (n >= 5 and opp_d > 2 * opp_c)
        or (rec_len >= 6 and r_opp_d >= 5)
    )
    forgiving_evidence = (
        d_to_c >= 2
        and d_to_d == 0
        and r_opp_c >= rec_len - 3
    )
    exploited_last = n >= 2 and me[-2] == 'D' and op[-1] == 'C'

    randomish = (
        n >= 12
        and my_d <= 5
        and opp_c * 10 >= 3 * n
        and opp_c * 10 <= 7 * n
        and op_alt * 10 >= 6 * (n - 1)
    )

    if randomish and not hostile and (last_op == 'D' or d_to_d == 0):
        return 'D' if rng.random() < 0.82 else 'C'

    if last_op == 'D':
        if hostile:
            return 'D'
        if last_me == 'C':
            if very_nice and cd <= 2 and d_to_d == 0 and rng.random() < 0.06:
                return 'C'
            return 'D'
        if n >= 95:
            return 'D'
        if very_nice or forgiving_evidence:
            return 'C' if rng.random() < 0.76 else 'D'
        return 'C' if rng.random() < 0.52 else 'D'

    if last_me == 'D':
        if forgiving_evidence:
            return 'D'
        if n >= 95:
            return 'C'
        if hostile:
            return 'C'
        if very_nice and d_to_d == 0:
            if opp_c == n:
                return 'D'
            return 'D' if rng.random() < 0.42 else 'C'
        if nice and exploited_last and d_to_d == 0 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if forgiving_evidence:
        return 'D'

    if randomish and d_to_d == 0:
        return 'D' if rng.random() < 0.55 else 'C'

    if n >= 85 and nice and d_to_d == 0:
        if n == 98:
            return 'C'
        if very_nice:
            if n >= 97:
                return 'D' if rng.random() < 0.18 else 'C'
            if n >= 95:
                return 'D' if rng.random() < 0.35 else 'C'
            if n >= 90:
                return 'D' if rng.random() < 0.12 else 'C'
            return 'D' if rng.random() < 0.04 else 'C'

    if very_nice and my_d == 0 and 25 <= n < 90 and rng.random() < 0.05:
        return 'D'

    if n >= 10 and not hostile and not very_nice and opp_c >= n // 2 and r_opp_c >= rec_len // 2:
        if my_d <= opp_d + 2 and rng.random() < 0.03:
            return 'D'

    return 'C'
